def icone(nom: str, taille: int = 20, classe: str = "", libelle: str | None = None) -> Markup:
    """SVG en ligne, à la couleur du texte (currentColor). Décoratif sauf si un libellé est fourni."""
    accessibilite = (
        Markup(' role="img" aria-label="{}"').format(libelle)
        if libelle
        else Markup(' aria-hidden="true"')
    )
    return Markup(
        '<svg xmlns="http://www.w3.org/2000/svg" width="{t}" height="{t}" viewBox="0 0 24 24" fill="none" '
        'stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" '
        'class="{c}" focusable="false"{a}>{contenu}</svg>'
    ).format(t=taille, c=classe, a=accessibilite, contenu=Markup(ICONES[nom]))
